L("جامعة الدول العربية", [61, 66],
  ["أن يعرف الطالب السياق التاريخي لنشأة الجامعة العربية.", "أن يحدد أهدافها ومبادئها وهياكلها.", "أن يقيم إنجازاتها وأداءها."],
  "أعرض صورة مقر الجامعة العربية بالقاهرة وأسأل: ما الذي يجمع الدول العربية؟",
  "أثناء الحرب العالمية الثانية شجعت بريطانيا تطلعات العرب، فظهرت مشاريع وحدوية: سوريا الكبرى، الهلال الخصيب، الاتحاد الشامل. ولرأب الصدع دعت مصر سنة 1943 إلى مشاورات (مصر، العراق، لبنان، اليمن، السعودية، شرقي الأردن، فلسطين) مهدت لاجتماع الإسكندرية (سبتمبر–أكتوبر 1944) الذي استبعد الدولة الفدرالية واتفق على كيان يتساوى فيه المؤسسون، ثم المؤتمر التأسيسي بالقاهرة في 22 مارس 1945. أهدافها: التعاون العربي والترابط ؛ ومبادئها: فض النزاعات سلميا (التحكيم) والدفاع المشترك. هياكلها: مجلس الجامعة (أعلى هيئة، دورتان عاديتان سنويا)، الأمانة العامة (أمين عام لخمس سنوات بأغلبية الثلثين)، المجالس الوزارية والمنظمات المتخصصة (الصندوق العربي للإنماء، صندوق النقد العربي، المصرف العربي للتنمية في إفريقيا، الألكسو). إنجازاتها: دعم استقلال لبنان وسوريا والمغرب، قرار مقاطعة الكيان الصهيوني (1950)، لاءات الخرطوم (1967)، تمويل المشاريع، نشر الثقافة العربية ؛ وفشلت محاولات الوحدة لغياب استراتيجيات اقتصادية صلبة.",
  ["المشاريع الوحدوية: سوريا الكبرى، الهلال الخصيب، الاتحاد الشامل.", "مشاورات 1943 ← اجتماع الإسكندرية 1944 ← التأسيس بالقاهرة 22 مارس 1945.", "المبادئ: الحل السلمي، الدفاع المشترك.", "الهياكل: المجلس، الأمانة العامة، المجالس والمنظمات المتخصصة.", "الحصيلة: دعم الاستقلال، مقاطعة إسرائيل، مؤسسات تنموية وثقافية، فشل مشاريع الوحدة."],
  ("لماذا فشلت محاولات الوحدة العربية حسب الدرس؟", "لغياب استراتيجيات اقتصادية صلبة تعضد الشراكة العربية وتضمن استمرار المشاريع الوحدوية."),
  [S("أولا: النشأة", table=[["التاريخ", "الحدث"], ["الحرب الثانية", "مشاريع: سوريا الكبرى، الهلال الخصيب، الاتحاد الشامل"], ["1943", "مشاورات بدعوة من مصر"], ["سبتمبر–أكتوبر 1944", "اجتماع الإسكندرية"], ["22 مارس 1945", "المؤتمر التأسيسي بالقاهرة: قيام الجامعة"]]),
   S("ثانيا: الأهداف والمبادئ", ["الأهداف: تحقيق التعاون العربي والترابط بين الشعوب.", "المبادئ: فض النزاعات بالطرق السلمية (التحكيم) ؛ الدفاع المشترك لصد الأطماع الأجنبية."]),
   S("ثالثا: الهياكل", table=[["الهيئة", "دورها"], ["مجلس الجامعة", "أعلى هيئة: ممثلو الدول، دورتان سنويا، الميزانية والدفاع عن الأعضاء"], ["الأمانة العامة", "الجهاز الإداري: أمين عام لخمس سنوات بأغلبية الثلثين"], ["المجالس والمنظمات", "مجلس الدفاع المشترك، المجلس الاقتصادي والاجتماعي، صندوق النقد العربي، المصرف العربي للتنمية في إفريقيا (1975)، الألكسو"]]),
   S("رابعا: الحصيلة", ["سياسيا: دعم استقلال لبنان وسوريا والمغرب ؛ قرار تحريم التعامل مع الكيان الصهيوني (فاتح أبريل 1950) ؛ مؤتمر الخرطوم 1967 ؛ محاولات وحدة فاشلة (مصر وسوريا 1958–1961…).", "اقتصاديا: الصندوق العربي للإنماء مول أكثر من 377 مشروعا في 17 دولة.", "ثقافيا: الألكسو، معهد البحوث والدراسات العربية، محو الأمية، تنسيق التعريب."]),
   S("ملاحظة", ["(تصحيح: في جدول محاولات الوحدة «1981 مشروع الوحدة بين سوريا ومصر وليبيا»، والمعروف أن اتحاد الجمهوريات العربية بين الدول الثلاث كان سنة 1971.)"])],
  apps=[("متى تأسست جامعة الدول العربية؟ وأين؟", "في 22 مارس 1945 بالقاهرة."), ("ما المنظمة العربية المختصة بالثقافة؟", "المنظمة العربية للتربية والثقافة والعلوم (الألكسو).")]),
L("الاتحاد الإفريقي", [67, 72],
  ["أن يعرف الطالب الجذور التاريخية لوحدة إفريقيا.", "أن يميز منظمة الوحدة الإفريقية من الاتحاد الإفريقي.", "أن يحدد أهداف الاتحاد ومبادئه وهيئاته وإنجازاته."],
  "أعرض صورة مقر الاتحاد الإفريقي في أديس أبابا وأسأل: هل يمكن أن تتحد قارة بخمسين دولة؟",
  "تعود جذور الوحدة الإفريقية إلى ق19 في الأوساط الزنجية الداعية إلى التحرر، ثم مؤتمرات باريس (1919) ولندن (1921) ولشبونة (1923) ونيويورك (1927) المطالبة بتقرير المصير. وبعد الاستقلالات انقسمت الدول إلى مجموعة الدار البيضاء (1961: المغرب، غينيا، غانا، مالي، حكومة الجزائر المؤقتة) ومجموعة مونروفيا (قريبة من الغرب، منها موريتانيا والسنغال)، ثم أعلن قيام منظمة الوحدة الإفريقية في 25 مايو 1963. وعلى أنقاضها قام الاتحاد الإفريقي: قمة لومي (2000) اعتمدت القانون التأسيسي، لوساكا (2001) خريطة الطريق، ديربان (2002) إطلاق الاتحاد. أهدافه: الوحدة والتضامن، الدفاع عن السيادة، التكامل السياسي والاقتصادي، الديمقراطية والحكم السديد، التنمية. مبادئه: المساواة، احترام الحدود الموروثة عند الاستقلال، منع استخدام القوة، عدم التدخل، حق طلب التدخل لإعادة السلم. هيئاته: الجمعية العامة، البرلمان الإفريقي (جوهانسبرغ)، المفوضية (أديس أبابا)، مجلس السلم والأمن (2004)، المجلس الاقتصادي والاجتماعي والثقافي، اللجان الفنية.",
  ["الجذور: مؤتمرات 1919–1927.", "مجموعتا الدار البيضاء ومونروفيا (1961).", "منظمة الوحدة الإفريقية: 25 مايو 1963.", "الاتحاد الإفريقي: لومي 2000، لوساكا 2001، ديربان 2002.", "الهيئات: الجمعية العامة، البرلمان، المفوضية، مجلس السلم والأمن."],
  ("ما مبدأ «احترام الحدود الموروثة عند الاستقلال»؟ ولماذا هو مهم؟", "التزام الدول بالحدود التي ورثتها عن الاستعمار تجنبا للنزاعات الحدودية بين الدول الإفريقية."),
  [S("أولا: الجذور ومنظمة الوحدة الإفريقية", table=[["التاريخ", "الحدث"], ["ق19", "الدعوة الزنجية إلى التحرر والوحدة"], ["1919–1927", "مؤتمرات باريس ولندن ولشبونة ونيويورك"], ["1961", "مجموعتا الدار البيضاء ومونروفيا"], ["25 مايو 1963", "قيام منظمة الوحدة الإفريقية"]]),
   S("ثانيا: نشأة الاتحاد الإفريقي", table=[["القمة", "السنة", "دورها"], ["لومي", "2000", "اعتماد القانون التأسيسي"], ["لوساكا", "2001", "خريطة طريق التنفيذ"], ["ديربان", "2002", "إطلاق الاتحاد (أول رئيس: تابو مبيكي)"]]),
   S("الأهداف والمبادئ", ["الأهداف: الوحدة والتضامن ؛ الدفاع عن السيادة ؛ التكامل السياسي والاقتصادي ؛ الديمقراطية والحكم السديد ؛ التنمية بالعلم والتكنولوجيا.", "المبادئ: المساواة ؛ احترام الحدود الموروثة ؛ منع استخدام القوة ؛ عدم التدخل ؛ حق طلب تدخل الاتحاد لإعادة السلم ؛ رفض الإفلات من العقاب والإرهاب."]),
   S("الهيئات", table=[["الهيئة", "خصائصها"], ["الجمعية العامة", "رؤساء الدول، اجتماع نصف سنوي بأديس أبابا"], ["البرلمان الإفريقي", "جوهانسبرغ، خمسة أعضاء عن كل دولة"], ["المفوضية", "الأمانة العامة بأديس أبابا"], ["مجلس السلم والأمن", "تأسس 2004، 15 عضوا"], ["المجلس الاقتصادي والاجتماعي والثقافي", "هيئة استشارية"]])],
  apps=[("أين يقع مقر الاتحاد الإفريقي؟", "في أديس أبابا (إثيوبيا)."), ("إلى أي مجموعة انتمت موريتانيا سنة 1961؟", "مجموعة مونروفيا.")]),
